   mask5 = weechat_string_replace (mask4,
                                   dir_separator,
                                   weechat_config_string (logger_config_file_replacement_char));
   if (!mask5)
        goto end;

#ifdef __CYGWIN__
   mask6 = weechat_string_replace (mask5, "\\",
