matchCurrentInput(
 		const InString *input, int pos, const widechar *passInstructions, int passIC) {
 	int k;
 	int kk = pos;
	for (k = passIC + 2; k < passIC + 2 + passInstructions[passIC + 1]; k++)
 		if (input->chars[kk] == ENDSEGMENT || passInstructions[k] != input->chars[kk++])
 			return 0;
 	return 1;
}

matchCurrentInput(
 		const InString *input, int pos, const widechar *passInstructions, int passIC) {
 	int k;
 	int kk = pos;
	for (k = passIC + 2;
			((k < passIC + 2 + passInstructions[passIC + 1]) && (kk < input->length));
			k++)
 		if (input->chars[kk] == ENDSEGMENT || passInstructions[k] != input->chars[kk++])
 			return 0;
 	return 1;
}

static void cliRefreshPrompt(void) {
   int len;
    if (config.eval_ldb) return;
   if (config.hostsocket != NULL)
       len = snprintf(config.prompt,sizeof(config.prompt),"redis %s",
                      config.hostsocket);
   else
       len = anetFormatAddr(config.prompt, sizeof(config.prompt),
                          config.hostip, config.hostport);
    /* Add [dbnum] if needed */
    if (config.dbnum != 0)
       len += snprintf(config.prompt+len,sizeof(config.prompt)-len,"[%d]",
           config.dbnum);
   snprintf(config.prompt+len,sizeof(config.prompt)-len,"> ");
}

static void cliRefreshPrompt(void) {
    if (config.eval_ldb) return;

   sds prompt = sdsempty();
   if (config.hostsocket != NULL) {
       prompt = sdscatfmt(prompt,"redis %s",config.hostsocket);
   } else {
       char addr[256];
       anetFormatAddr(addr, sizeof(addr), config.hostip, config.hostport);
       prompt = sdscatlen(prompt,addr,strlen(addr));
   }

    /* Add [dbnum] if needed */
    if (config.dbnum != 0)
       prompt = sdscatfmt(prompt,"[%i]",config.dbnum);

   /* Copy the prompt in the static buffer. */
   prompt = sdscatlen(prompt,"> ",2);
   snprintf(config.prompt,sizeof(config.prompt),"%s",prompt);
   sdsfree(prompt);
}

static int jpeg_size(unsigned char* data, unsigned int data_size,
                     int *width, int *height)
{
    int i = 0;
    if (i + 3 < data_size && data[i] == 0xFF && data[i+1] == 0xD8 &&
            data[i+2] == 0xFF && data[i+3] == 0xE0) {
        i += 4;
        if(i + 6 < data_size &&
                data[i+2] == 'J' && data[i+3] == 'F' && data[i+4] == 'I' &&
                data[i+5] == 'F' && data[i+6] == 0x00) {
            unsigned short block_length = data[i] * 256 + data[i+1];
            while(i<data_size) {
                i+=block_length;
                if((i + 1) >= data_size)
                    return -1;
                if(data[i] != 0xFF)
                    return -1;
                if(data[i+1] == 0xC0) {
                    *height = data[i+5]*256 + data[i+6];
                    *width = data[i+7]*256 + data[i+8];
                     return 0;
                 }
                 i+=2;
                block_length = data[i] * 256 + data[i+1];
             }
         }
     }

    return -1;
}

